package com.android.launcher3;import android.content.*;import android.os.*;
public final class LunatikBlurExport {
 public static void ensureDefaults(Context c){SharedPreferences p=c.getSharedPreferences("com.android.launcher3.prefs",0);SharedPreferences.Editor e=p.edit();boolean changed=false;if(!p.contains("pref_blur_depth")){e.putInt("pref_blur_depth",60);changed=true;}if(!p.contains("pref_app_drawer_opacity")){e.putInt("pref_app_drawer_opacity",25);changed=true;}if(!p.contains("pref_app_drawer_custom_color_enabled")){e.putBoolean("pref_app_drawer_custom_color_enabled",true);changed=true;}if(!p.contains("pref_app_drawer_custom_color_dark")){e.putInt("pref_app_drawer_custom_color_dark",0xff000000);changed=true;}if(changed)e.commit();}
public static Bundle read(Context c){Bundle b=new Bundle();if(Binder.getCallingUid()!=1000&&Binder.getCallingUid()!=android.os.Process.myUid())return b;SharedPreferences p=c.getSharedPreferences("com.android.launcher3.prefs",0);int r=Math.max(0,Math.min(150,p.getInt("pref_blur_depth",60)));int a=Math.max(0,Math.min(100,p.getInt("pref_app_drawer_opacity",25)));int alpha=a*255/100;int d=(int)Math.round(100*(1-Math.pow(1-alpha/255.0,2)));b.putBoolean("ok",true);b.putInt("radius",r);b.putInt("darkness",d);return b;}}
